from __future__ import annotations

import contextlib
import os
import shutil
import stat
import subprocess
import tarfile
import tempfile
import time
from datetime import datetime
from pathlib import Path
from typing import TYPE_CHECKING, cast

from backup.shared.bkpignore import (
    BKPIGNORE_FILENAME,
    ExcludeState,
    state_for_directory,
)
from backup.step_result import ArchiveMeta, PlanEntry, ProgressEvent, StepResult

if TYPE_CHECKING:
    import threading
    from collections.abc import Callable, Iterable, Iterator, Mapping

__all__ = ["ArchiveCancelled", "TarArchive", "WalkResult", "resolve_paths"]

_ARCHIVE_MODE = 0o600
_ENGINE_PYTHON = "python-tarfile"
_ENGINE_SYSTEM_TAR = "system-tar"


class ArchiveCancelled(Exception):
    """Archive creation stopped before publication."""


def _check_cancel(cancel: threading.Event | None) -> None:
    if cancel is not None and cancel.is_set():
        raise ArchiveCancelled


def _emit_progress(progress: Callable[[ProgressEvent], None] | None, event: ProgressEvent) -> None:
    if progress is not None:
        with contextlib.suppress(Exception):
            progress(event)


def _start_archive_progress(
    label: str, total: int, engine: str, progress: Callable[[ProgressEvent], None] | None
) -> tuple[Callable[[int], None] | None, Callable[[], None]]:
    done = 0 if engine == _ENGINE_PYTHON else None
    reported = done
    emitted_at = time.monotonic()
    _emit_progress(progress, ProgressEvent(label, "archiving", done, total))

    def on_bytes(count: int) -> None:
        nonlocal done, reported, emitted_at
        done = count
        now = time.monotonic()
        if now - emitted_at >= 0.2:
            _emit_progress(progress, ProgressEvent(label, "archiving", done, total))
            reported, emitted_at = done, now

    def on_finalize() -> None:
        if done != reported:
            _emit_progress(progress, ProgressEvent(label, "archiving", done, total))
        _emit_progress(progress, ProgressEvent(label, "finalizing", done, total))

    return (on_bytes if engine == _ENGINE_PYTHON and progress is not None else None), on_finalize


class WalkResult:
    """The outcome of walking + filtering a source tree, before any archive.

    ``files`` is the ordered list of archive MEMBERS as absolute paths:
    surviving directories first (parent-first, so a restore recreates the tree
    including empty dirs), then regular files, then symlinks (each archived as
    the link itself, not followed, matching the former tar backup). ``file_count``
    counts only the regular files (not dirs or symlinks) and ``total_bytes`` sums
    their input sizes (a symlink/dir contributes 0). ``applied`` lists the
    ``.bkpignore`` rules that fired anywhere in the tree (for dry-run reporting).
    """

    def __init__(
        self: WalkResult,
        files: list[Path],
        total_bytes: int,
        applied: list[str],
        file_count: int,
    ) -> None:
        self.files = files
        self.total_bytes = total_bytes
        self.applied = applied
        self._file_count = file_count

    @property
    def file_count(self: WalkResult) -> int:
        return self._file_count


class TarArchive:
    """Tar a source tree into a compressed, ``chmod 600``, atomically-written archive.

    File selection is owned here: it :func:`os.walk`s ``source`` top-down,
    layering each directory's ``.bkpignore`` rules onto the exclude state
    inherited from its ancestors (so ``!target`` un-ignores are path-scoped to
    the file's own subtree), and adds surviving files to a
    ``tarfile.open(mode="w:gz")``. The archive is streamed to a sibling temp
    file, ``fsync``ed, ``chmod 600``ed, then ``os.replace``d into ``out`` — so a
    crash or ENOSPC never leaves a partial ``.tar.gz`` at the final path.
    """

    @property
    def inputs(self: TarArchive) -> Mapping[str, object]:
        return {"source": "", "out": "", "engine": _ENGINE_PYTHON, "items": None}

    def plan(self: TarArchive, **kwargs: object) -> PlanEntry:
        label, engine, source_raw, out_raw, now = _parse_inputs(kwargs)
        message = _missing_input(source_raw, out_raw)
        if message:
            source_text = str(os.path.normpath(Path(source_raw).expanduser())) if source_raw else ""
            out_text = str(Path(_expand_stamp(out_raw, now)).expanduser()) if out_raw else ""
            replaces = Path(out_text).exists() if out_text else False
            return PlanEntry(label, source_text, out_text, "fail", message, replaces)
        source, out = resolve_paths(source_raw, out_raw, now)
        replaces = out.exists()
        if engine not in (_ENGINE_PYTHON, _ENGINE_SYSTEM_TAR):
            status = "fail"
            reason = f"unknown engine '{engine}'; expected {_ENGINE_PYTHON} or {_ENGINE_SYSTEM_TAR}"
        else:
            status, reason = _plan_source(label, source, out, kwargs.get("items"))
        return PlanEntry(label, str(source), str(out), status, reason, replaces)

    def run(self: TarArchive, **kwargs: object) -> Iterator[StepResult]:
        _check_cancel(cast("threading.Event | None", kwargs.get("cancel")))
        label, engine, source_raw, out_raw, now = _parse_inputs(kwargs)
        message = _missing_input(source_raw, out_raw)
        if message:
            yield StepResult(label, success=False, message=message)
            return

        source, out = resolve_paths(source_raw, out_raw, now)

        if engine not in (_ENGINE_PYTHON, _ENGINE_SYSTEM_TAR):
            yield StepResult(
                label,
                success=False,
                message=f"unknown engine '{engine}'; expected {_ENGINE_PYTHON} or {_ENGINE_SYSTEM_TAR}",
            )
            return

        kind = _source_kind(source)
        if kind != "dir":
            missing_source = kind == "missing"
            reason = "source not found" if missing_source else "source is not a directory"
            yield StepResult(label, success=missing_source, message=f"{reason}: {source}", skipped=missing_source)
            return

        containment = _reject_out_inside_source(label, source, out, kwargs.get("items"))
        if containment is not None:
            yield containment
            return

        yield from self._run_validated(label, engine, source, out, kwargs)

    def _run_validated(
        self: TarArchive,
        label: str,
        engine: str,
        source: Path,
        out: Path,
        kwargs: dict[str, object],
    ) -> Iterator[StepResult]:
        cancel = cast("threading.Event | None", kwargs.get("cancel"))
        _check_cancel(cancel)
        dry_run = bool(kwargs.get("dry_run", False))
        progress = cast("Callable[[ProgressEvent], None] | None", kwargs.get("progress"))
        progress = None if dry_run else progress
        base_state = ExcludeState(base_excludes=frozenset(_as_str_tuple(kwargs.get("excludes", ()))))
        missing: list[str] = []
        bundle = kwargs.get("items") is not None
        if bundle:
            try:
                selected = _normalize_items(source, kwargs["items"])
            except ValueError as exc:
                yield StepResult(label, success=False, message=str(exc))
                return
            _emit_progress(progress, ProgressEvent(label, "scanning", None, None))
            try:
                walk, missing = _select_items(source, base_state, selected)
            except OSError as exc:
                yield StepResult(label, success=False, message=str(exc))
                return
            _check_cancel(cancel)
            if not walk.files:
                yield StepResult(label, success=True, message=_no_items_message(source, missing), skipped=True)
                return
        else:
            _emit_progress(progress, ProgressEvent(label, "scanning", None, None))
            walk = _walk_tree(source, base_state)
            _check_cancel(cancel)

        if dry_run:
            result = self._dry_run_result(label, out, walk)
        else:
            result = self._archive_result(
                label, source if bundle else source.parent, out, walk, engine, cancel=cancel, progress=progress
            )
        if missing:
            result.message += f"; missing items: {', '.join(missing)}"
        yield result

    @staticmethod
    def _dry_run_result(label: str, out: Path, walk: WalkResult) -> StepResult:
        applied = ", ".join(walk.applied) if walk.applied else "none"
        message = (
            f"would archive {walk.file_count} files ({walk.total_bytes} bytes) "
            f"-> {out}; .bkpignore rules applied: {applied}"
        )
        return StepResult(
            label,
            success=True,
            message=message,
            archive=ArchiveMeta(out_path=str(out), file_count=walk.file_count, total_bytes=walk.total_bytes),
        )

    @staticmethod
    def _archive_result(  # noqa: PLR0913 — retain archive context plus keyword-only cancellation
        label: str,
        arcbase: Path,
        out: Path,
        walk: WalkResult,
        engine: str,
        *,
        cancel: threading.Event | None = None,
        progress: Callable[[ProgressEvent], None] | None = None,
    ) -> StepResult:
        _check_cancel(cancel)
        out.parent.mkdir(parents=True, exist_ok=True)
        on_bytes, on_finalize = _start_archive_progress(label, walk.total_bytes, engine, progress)
        note = ""
        if engine == _ENGINE_SYSTEM_TAR:
            finalized = False

            def finalize_once() -> None:
                nonlocal finalized
                finalized = True
                on_finalize()

            fallback = _write_archive_system_tar(out, arcbase, walk.files, cancel=cancel, on_finalize=finalize_once)
            if fallback is not None:
                if finalized:
                    _, on_finalize = _start_archive_progress(label, walk.total_bytes, engine, progress)
                _write_archive(out, arcbase, walk.files, cancel=cancel, on_finalize=on_finalize)
                note = f" (system-tar unavailable: {fallback}; used python engine)"
        else:
            _write_archive(out, arcbase, walk.files, cancel=cancel, on_bytes=on_bytes, on_finalize=on_finalize)
        size = out.stat().st_size
        return StepResult(
            label,
            success=True,
            message=(
                f"archived {walk.file_count} files -> {out} ({walk.total_bytes} bytes in, {size} bytes on disk){note}"
            ),
            archive=ArchiveMeta(out_path=str(out), file_count=walk.file_count, total_bytes=walk.total_bytes),
        )


def _reject_out_inside_source(label: str, source: Path, out: Path, items: object = None) -> StepResult | None:
    """Reject an ``out`` path that would be re-archived by the run.

    An ``out`` under ``source`` makes each run re-archive the previous run's
    archive (unbounded recursive growth). ``out`` may not exist yet, so its
    PARENT is resolved (which does exist — a stamp only expands the basename) and
    the name rejoined, giving a real absolute path to test for containment
    against the resolved source. A whole-tree run rejects ``out`` anywhere in
    ``source``; a bundle rejects ``out`` equal to the source or equal to or
    inside a selected item (invalid ``items`` fail first). Returns a failed
    :class:`StepResult` (the caller yields it and returns before walking),
    otherwise ``None``.
    """
    selected: list[Path] = []
    if items is not None:
        try:
            selected = _normalize_items(source, items)
        except ValueError as exc:
            return StepResult(label, success=False, message=str(exc))
    source_resolved = source.resolve()
    out_resolved = out.parent.resolve() / out.name
    if out_resolved == source_resolved or (items is None and source_resolved in out_resolved.parents):
        return StepResult(
            label,
            success=False,
            message=(f"out path {out} is inside source {source}; choose an out path outside the backup source"),
        )
    for relative in selected:
        item = source_resolved / relative
        if out_resolved == item or item in out_resolved.parents:
            return StepResult(
                label,
                success=False,
                message=(
                    f"out path {out} is inside selected item {source / relative}; "
                    "choose an out path outside the bundle's items"
                ),
            )
    return None


def _no_items_message(source: Path, missing: list[str]) -> str:
    tail = f"; missing items: {', '.join(missing)}" if missing else ""
    return f"no selected items to archive in {source}{tail}"


def _plan_items(source: Path, items: object) -> tuple[str, str]:
    """Return the plan ``(status, reason)`` for a bundle's ``items``."""
    try:
        selected = _normalize_items(source, items)
        found = any(_item_present(source / item) for item in selected)
    except (ValueError, OSError) as exc:
        return "fail", str(exc)
    if found:
        return "run", ""
    return "skip", _no_items_message(source, [item.as_posix() for item in selected])


def _source_kind(source: Path) -> str:
    """Classify ``source`` as ``dir``, ``file`` or ``missing``; other OSErrors propagate.

    ``Path.is_dir``/``exists`` report False on EACCES (Python 3.14), which would
    turn an unreadable source into a silent skip.
    """
    try:
        mode = os.stat(source).st_mode
    except (FileNotFoundError, NotADirectoryError):
        return "missing"
    return "dir" if stat.S_ISDIR(mode) else "file"


def _plan_source(label: str, source: Path, out: Path, items: object) -> tuple[str, str]:
    """Return the plan ``(status, reason)`` once the engine is valid."""
    try:
        kind = _source_kind(source)
    except OSError as exc:
        return "fail", str(exc)
    if kind == "missing":
        return "skip", f"source not found: {source}"
    if kind == "file":
        return "fail", f"source is not a directory: {source}"
    containment = _reject_out_inside_source(label, source, out, items)
    if containment is not None:
        return "fail", containment.message
    if items is not None:
        return _plan_items(source, items)
    return "run", ""


def _item_present(path: Path) -> bool:
    """Return whether ``path`` exists; only absence counts as missing, other OSErrors propagate."""
    try:
        os.lstat(path)
    except (FileNotFoundError, NotADirectoryError):
        return False
    return True


def _normalize_items(source: Path, items: object) -> list[Path]:
    """Validate literal item paths and remove duplicate selected subtrees."""
    if not isinstance(items, (list, tuple)) or not all(isinstance(item, str) for item in items):
        raise ValueError("items must be a list of relative paths")
    if not items:
        raise ValueError("items must not be empty")
    selected: list[Path] = []
    for item in items:
        relative = Path(os.path.normpath(item))
        if not item or relative.is_absolute() or relative == Path(".") or relative.parts[0] == "..":
            raise ValueError(f"invalid item '{item}': must be a relative path inside the source")
        for parent in reversed(relative.parents):
            if parent != Path(".") and (source / parent).is_symlink():
                raise ValueError(f"item '{item}' passes through symlink '{parent.as_posix()}'")
        if relative not in selected and not any(parent in selected for parent in relative.parents):
            selected = [path for path in selected if relative not in path.parents]
            selected.append(relative)
    return selected


def _select_items(source: Path, base_state: ExcludeState, selected: list[Path]) -> tuple[WalkResult, list[str]]:
    """Select bundle members using source-relative excludes and ancestor rules."""
    files: list[Path] = []
    missing: list[str] = []
    total_bytes = file_count = 0
    states: dict[str, ExcludeState] = {str(source): state_for_directory(source, base_state)}
    applied: list[str] = []
    for relative in selected:
        path = source / relative
        if not _item_present(path):
            missing.append(relative.as_posix())
            continue
        metadata = path.lstat()
        state = states[str(source)]
        for index, component in enumerate(relative.parts):
            ancestor = source.joinpath(*relative.parts[: index + 1])
            relpath = ancestor.relative_to(source).as_posix()
            if state.is_excluded(component, relpath):
                break
            if index < len(relative.parts) - 1:
                state = state_for_directory(ancestor, state)
                states[str(ancestor)] = state
                continue
            if stat.S_ISDIR(metadata.st_mode):
                subtree = _walk_tree(path, state, root=source)
                files.extend(subtree.files)
                file_count += subtree.file_count
                total_bytes += subtree.total_bytes
                applied.extend(subtree.applied)
            elif component != BKPIGNORE_FILENAME:
                if stat.S_ISREG(metadata.st_mode):
                    file_count += 1
                    total_bytes += metadata.st_size
                    files.append(path)
                elif stat.S_ISLNK(metadata.st_mode):
                    files.append(path)
    rules = list(dict.fromkeys([*_collect_applied(states), *applied]))
    return WalkResult(files, total_bytes, rules, file_count), missing

from __future__ import annotations

import tarfile
from typing import TYPE_CHECKING

import pytest
from buvis.pybase.result import FatalError

from backup.capabilities.tar_archive import TarArchive
from backup.config import BackupConfig
from backup.runner import Runner

if TYPE_CHECKING:
    from pathlib import Path

    from pytest_mock import MockerFixture

    from backup.step_result import PlanEntry, StepResult


def _source(root: Path, name: str) -> Path:
    source = root / name
    source.mkdir(parents=True)
    (source / "tiny.txt").write_bytes(name.encode())
    (source / "tiny.txt-copy").write_bytes(f"{name}-copy".encode())
    return source


def _invoke(interface: str, mode: str, values: dict[str, object]) -> list[PlanEntry | StepResult]:
    if interface == "capability":
        archive = TarArchive()
        if mode == "plan":
            return [archive.plan(label="selected", **values)]
        return list(archive.run(label="selected", dry_run=mode == "dry-run", **values))
    cfg = BackupConfig.model_validate({"instances": {"selected": {"use": "tar-archive", "with": values}}})
    runner = Runner(cfg, dry_run=mode == "dry-run")
    selected = list(cfg.instances.items())
    return runner.plan(selected) if mode == "plan" else list(runner.run(selected))


def _assert_archive(out: Path, name: str) -> None:
    with tarfile.open(out, "r:gz") as archive:
        files = {member.name for member in archive.getmembers() if member.isfile()}
        assert files == {f"{name}/tiny.txt", f"{name}/tiny.txt-copy"}
        for filename, payload in (("tiny.txt", name), ("tiny.txt-copy", f"{name}-copy")):
            member = archive.extractfile(f"{name}/{filename}")
            assert member is not None
            assert member.read() == payload.encode()


def _snapshot(root: Path) -> dict[str, bytes | None]:
    return {str(path.relative_to(root)): path.read_bytes() if path.is_file() else None for path in root.rglob("*")}


@pytest.mark.parametrize("interface", ["capability", "runner"])
@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize("name", ["notes", "photos"])
def test_empty_engine_matches_omitted_python_engine(tmp_path: Path, interface: str, mode: str, name: str) -> None:
    source = _source(tmp_path / "sources", name)
    out = tmp_path / "archives" / f"{name}.tar.gz"
    values = {"source": str(source), "out": str(out)}
    omitted = _invoke(interface, "plan", values)
    results = _invoke(interface, mode, {**values, "engine": ""})

    assert len(omitted) == len(results) == 1
    assert omitted[0].status == "run"
    result = results[0]
    assert result.label == "selected"
    if mode == "plan":
        assert result == omitted[0]
        assert result.source == str(source)
        assert result.out == str(out)
        assert result.replaces is False
    else:
        assert result.success is True
        assert result.skipped is False
        assert result.out_path == str(out)
    assert out.exists() is (mode == "run")
    assert out.parent.exists() is (mode == "run")
    if mode == "run":
        _assert_archive(out, name)
    assert (source / "tiny.txt").read_bytes() == name.encode()
    assert (source / "tiny.txt-copy").read_bytes() == f"{name}-copy".encode()


@pytest.mark.parametrize("interface", ["capability", "runner"])
@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize(("key", "message"), [("source", "no source configured"), ("out", "no out path configured")])
@pytest.mark.parametrize("existing", [False, True])
def test_empty_paths_fail_without_using_cwd_or_changing_artifacts(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, interface: str, mode: str, key: str, message: str, existing: bool
) -> None:
    source = _source(tmp_path / "sources", "notes")
    cwd = _source(tmp_path, "working")
    monkeypatch.chdir(cwd)
    out = tmp_path / "archives" / "notes.tar.gz"
    if existing:
        out.parent.mkdir()
        out.write_bytes(b"keep existing archive")
    values = {"source": str(source), "out": str(out), key: ""}
    before = _snapshot(tmp_path)

    results = _invoke(interface, mode, values)

    assert len(results) == 1
    result = results[0]
    assert result.label == "selected"
    if mode == "plan":
        assert result.status == "fail"
        assert result.reason == message
        if key == "out":
            assert result.out == ""
            assert result.replaces is False
    else:
        assert result.success is False
        assert result.skipped is False
        assert result.message == message
    assert _snapshot(tmp_path) == before


def _mixed_config(tmp_path: Path) -> tuple[BackupConfig, Path]:
    shared = tmp_path / "shared.tar.gz"
    shared.write_bytes(b"preserve duplicate archive")
    values = {}
    for name in ("empty", "empty-copy", "missing", "missing-copy", "same", "same-copy", "notes", "notes-copy"):
        source = _source(tmp_path / "sources", name)
        out = str(tmp_path / "outputs" / f"{name}.tar.gz")
        if name in {"empty", "empty-copy"}:
            out = ""
        elif name in {"same", "same-copy"}:
            out = str(shared)
        values[name] = {"source": "" if name in {"missing", "missing-copy"} else str(source), "out": out}
    cfg = BackupConfig.model_validate(
        {"instances": {name: {"use": "tar-archive", "with": value} for name, value in values.items()}}
    )
    return cfg, shared


@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
def test_runner_keeps_missing_inputs_distinct_from_collisions_and_executes_independent_instances(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, mode: str
) -> None:
    cfg, shared = _mixed_config(tmp_path)
    cwd = _source(tmp_path, "working")
    before_cwd = _snapshot(cwd)
    monkeypatch.chdir(cwd)
    runner = Runner(cfg, dry_run=mode == "dry-run")
    selected = list(cfg.instances.items())

    results = runner.plan(selected) if mode == "plan" else list(runner.run(selected))

    labels = [result.label for result in results]
    if mode == "plan":
        assert labels == list(cfg.instances)
    else:
        assert sorted(labels) == sorted(cfg.instances)
        assert labels[:-2] == ["empty", "empty-copy", "missing", "missing-copy", "same", "same-copy"]
    for result in results:
        name = result.label
        if name in {"notes", "notes-copy"}:
            assert result.status == "run" if mode == "plan" else result.success is True
            out = tmp_path / "outputs" / f"{name}.tar.gz"
            assert out.exists() is (mode == "run")
            if mode == "run":
                _assert_archive(out, name)
            continue
        message = "no out path configured" if name in {"empty", "empty-copy"} else "no source configured"
        if name in {"same", "same-copy"}:
            other = "same-copy" if name == "same" else "same"
            message = f"output '{shared}' is also the output of '{other}'"
        assert result.status == "fail" if mode == "plan" else result.success is False
        assert (result.reason if mode == "plan" else result.message) == message
    expected = {shared}
    if mode == "run":
        expected |= {tmp_path / "outputs" / f"{name}.tar.gz" for name in ("notes", "notes-copy")}
    assert set(tmp_path.rglob("*.tar.gz")) == expected
    assert shared.read_bytes() == b"preserve duplicate archive"
    assert _snapshot(cwd) == before_cwd
    assert (tmp_path / "outputs").exists() is (mode == "run")


@pytest.mark.parametrize("interface", ["capability", "runner"])
@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
@pytest.mark.parametrize("engine", ["python-tarfile-copy", "copy-python-tarfile"])
def test_engine_lookalikes_remain_rejected_without_archive_effects(
    tmp_path: Path, interface: str, mode: str, engine: str
) -> None:
    source = _source(tmp_path / "sources", "photos")
    out = tmp_path / "archives" / "photos.tar.gz"
    out.parent.mkdir()
    out.write_bytes(b"preserve rejected engine archive")
    before = _snapshot(tmp_path)

    results = _invoke(interface, mode, {"source": str(source), "out": str(out), "engine": engine})

    assert len(results) == 1
    assert results[0].label == "selected"
    assert results[0].status == "fail" if mode == "plan" else results[0].success is False
    message = results[0].reason if mode == "plan" else results[0].message
    assert f"unknown engine '{engine}'" in message
    assert _snapshot(tmp_path) == before


@pytest.mark.parametrize("interface", ["capability", "runner"])
@pytest.mark.parametrize("message", ["archive storage unavailable", "archive permission denied"])
def test_fatal_archive_errors_follow_interface_contract_with_empty_default_engine(
    tmp_path: Path, mocker: MockerFixture, interface: str, message: str
) -> None:
    source = _source(tmp_path / "sources", "notes")
    out = tmp_path / "notes.tar.gz"
    mocker.patch("tarfile.open", autospec=True, side_effect=FatalError(message))

    values = {"source": str(source), "out": str(out), "engine": ""}
    if interface == "capability":
        with pytest.raises(FatalError, match=message):
            _invoke(interface, "run", values)
    else:
        results = _invoke(interface, "run", values)
        assert len(results) == 1
        assert results[0].label == "selected"
        assert results[0].success is False
        assert results[0].skipped is False
        assert results[0].message == f"selected failed: {message}"
        assert results[0].archive is None

    assert not out.exists()
    assert (source / "tiny.txt").read_bytes() == b"notes"
    assert (source / "tiny.txt-copy").read_bytes() == b"notes-copy"


@pytest.mark.parametrize("mode", ["plan", "run", "dry-run"])
def test_runner_empty_selection_has_no_archive_effects(tmp_path: Path, mode: str) -> None:
    source = _source(tmp_path / "sources", "unselected")
    cfg = BackupConfig.model_validate(
        {"instances": {"unselected": {"use": "tar-archive", "with": {"source": str(source), "out": ""}}}}
    )
    before = _snapshot(tmp_path)
    runner = Runner(cfg, dry_run=mode == "dry-run")

    results = runner.plan([]) if mode == "plan" else list(runner.run([]))

    assert results == []
    assert _snapshot(tmp_path) == before

